-- ---------------------------------------------------------------------------
-- registrations — one person's ticket/RSVP for one event
-- ---------------------------------------------------------------------------
create function public.generate_ticket_number()
returns text
language sql
volatile
set search_path = ''
as $$
  select 'KT-' || to_char(now() at time zone 'Asia/Kolkata', 'YYMMDD') || '-' ||
         upper(substr(md5(gen_random_uuid()::text), 1, 6));
$$;

create table public.registrations (
  id                       uuid primary key default gen_random_uuid(),
  event_id                 uuid not null references public.events (id) on delete restrict,
  user_id                  uuid not null references public.users (id) on delete restrict,
  ticket_number            text not null unique default public.generate_ticket_number(),
  -- secret in the attendee's QR code; hosts scan it to check in (2 × 122 random bits)
  check_in_token           text not null unique
                           default replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
  status                   public.registration_status not null,
  -- money snapshot at registration time, so later setting changes never
  -- rewrite historical revenue
  ticket_amount            integer not null default 0 check (ticket_amount >= 0), -- paise, owed to the organiser
  platform_fee             integer not null default 0 check (platform_fee >= 0),  -- paise, Kootam's revenue
  total_amount             integer not null default 0 check (total_amount >= 0),  -- what the attendee pays
  platform_fee_percentage  numeric(5, 2) not null default 0 check (platform_fee_percentage between 0 and 100),
  payment_status           public.registration_payment_status not null default 'NOT_REQUIRED',
  hold_expires_at          timestamptz, -- PENDING_PAYMENT seats are held only until this time
  checked_in_at            timestamptz,
  checked_in_by            uuid references public.users (id) on delete set null,
  cancelled_at             timestamptz,
  cancellation_reason      text check (char_length(cancellation_reason) <= 500),
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),
  check (total_amount = ticket_amount + platform_fee),
  check (status <> 'PENDING_PAYMENT' or hold_expires_at is not null),
  check ((status = 'CHECKED_IN') = (checked_in_at is not null))
);
create index registrations_event_idx on public.registrations (event_id, status);
create index registrations_user_idx on public.registrations (user_id);
-- waitlist order = created_at among WAITLISTED rows
create index registrations_waitlist_idx on public.registrations (event_id, created_at) where status = 'WAITLISTED';
-- One live registration per person per event, whatever the application does.
create unique index registrations_one_live_per_user
  on public.registrations (event_id, user_id)
  where status in ('PENDING_PAYMENT', 'CONFIRMED', 'WAITLISTED', 'CHECKED_IN', 'NO_SHOW');
create trigger registrations_updated_at before update on public.registrations
  for each row execute function public.set_updated_at();

-- Seats taken = confirmed/attended + payment holds that have not expired.
-- VOLATILE on purpose: after waiting on the event row lock it must take a
-- fresh snapshot, or it would miss the seat that was just committed.
create function public.event_seats_taken(target_event_id uuid)
returns integer
language sql
volatile
security definer
set search_path = ''
as $$
  select count(*)::integer from public.registrations r
  where r.event_id = target_event_id
    and (
      r.status in ('CONFIRMED', 'CHECKED_IN', 'NO_SHOW')
      or (r.status = 'PENDING_PAYMENT' and r.hold_expires_at > now())
    );
$$;

-- Event state machine:
--   DRAFT     → PUBLISHED | CANCELLED
--   PUBLISHED → CANCELLED | COMPLETED
-- Hosts (role "authenticated") may publish and may cancel a DRAFT. Cancelling
-- or completing a PUBLISHED event goes through server code, because it
-- triggers refunds / no-show marking.
create function public.enforce_event_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  privileged boolean := public.is_privileged();
  community record;
  seats integer;
begin
  if tg_op = 'INSERT' and new.status <> 'DRAFT' and not privileged then
    raise exception 'New events start as DRAFT' using errcode = 'check_violation';
  end if;

  if tg_op = 'UPDATE' and new.status is distinct from old.status then
    if not (
      (old.status = 'DRAFT'     and new.status in ('PUBLISHED', 'CANCELLED')) or
      (old.status = 'PUBLISHED' and new.status in ('CANCELLED', 'COMPLETED'))
    ) then
      raise exception 'Invalid event transition % -> %', old.status, new.status
        using errcode = 'check_violation';
    end if;
    if not privileged and old.status = 'PUBLISHED' then
      raise exception 'Event transition % -> % requires the server', old.status, new.status
        using errcode = 'insufficient_privilege';
    end if;
  end if;

  if new.status = 'PUBLISHED' and (tg_op = 'INSERT' or old.status <> 'PUBLISHED') then
    select status, payout_status into community from public.communities where id = new.community_id;
    if community.status <> 'ACTIVE' then
      raise exception 'Community is suspended' using errcode = 'check_violation';
    end if;
    if new.pricing <> 'FREE' and community.payout_status <> 'VERIFIED' then
      raise exception 'Paid events need a verified payout account' using errcode = 'check_violation';
    end if;
    new.published_at := coalesce(new.published_at, now());
  end if;

  if tg_op = 'UPDATE' then
    if new.community_id is distinct from old.community_id then
      raise exception 'Events cannot move between communities' using errcode = 'check_violation';
    end if;

    if old.status in ('CANCELLED', 'COMPLETED') and not privileged then
      raise exception 'Event is % and can no longer be edited', old.status using errcode = 'check_violation';
    end if;

    if (new.pricing is distinct from old.pricing or new.price is distinct from old.price)
       and exists (select 1 from public.registrations r where r.event_id = new.id) then
      raise exception 'Price cannot change once people have registered' using errcode = 'check_violation';
    end if;

    if new.capacity is not null and new.capacity is distinct from old.capacity then
      seats := public.event_seats_taken(new.id);
      if new.capacity < seats then
        raise exception 'Capacity cannot go below the % seats already taken', seats using errcode = 'check_violation';
      end if;
    end if;
  end if;

  return new;
end;
$$;
create trigger events_enforce_rules before insert or update on public.events
  for each row execute function public.enforce_event_rules();

-- Registration state machine:
--   PENDING_PAYMENT → CONFIRMED | CANCELLED
--   WAITLISTED      → PENDING_PAYMENT | CONFIRMED | CANCELLED
--   CONFIRMED       → CHECKED_IN | CANCELLED | NO_SHOW
--   CHECKED_IN, NO_SHOW, CANCELLED are terminal (refunds live on payments).
-- Every move into a seat-holding status locks the event row and re-checks
-- capacity, so two people can never take the last seat at the same time.
create function public.enforce_registration_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  ev record;
  takes_seat boolean := new.status in ('PENDING_PAYMENT', 'CONFIRMED');
begin
  if tg_op = 'UPDATE' then
    if new.status is distinct from old.status and not (
      (old.status = 'PENDING_PAYMENT' and new.status in ('CONFIRMED', 'CANCELLED')) or
      (old.status = 'WAITLISTED'      and new.status in ('PENDING_PAYMENT', 'CONFIRMED', 'CANCELLED')) or
      (old.status = 'CONFIRMED'       and new.status in ('CHECKED_IN', 'CANCELLED', 'NO_SHOW'))
    ) then
      raise exception 'Invalid registration transition % -> %', old.status, new.status
        using errcode = 'check_violation';
    end if;
    if new.event_id is distinct from old.event_id or new.user_id is distinct from old.user_id
       or new.ticket_amount is distinct from old.ticket_amount or new.platform_fee is distinct from old.platform_fee
       or new.check_in_token is distinct from old.check_in_token then
      raise exception 'Registration details are frozen' using errcode = 'check_violation';
    end if;
    -- A live payment hold keeps its seat; a waitlisted person, or one whose
    -- hold already lapsed, has to win a seat again.
    takes_seat := takes_seat and new.status is distinct from old.status and (
      old.status = 'WAITLISTED' or (old.status = 'PENDING_PAYMENT' and old.hold_expires_at <= now())
    );
    if new.status = 'CANCELLED' and new.cancelled_at is null then
      new.cancelled_at := now();
    end if;
  end if;

  -- Lock the event row: serialises every seat claim for this event.
  select status, capacity, pricing, registration_closes_at, starts_at
    into ev from public.events where id = new.event_id for update;

  if tg_op = 'INSERT' then
    if ev.status <> 'PUBLISHED' or now() > coalesce(ev.registration_closes_at, ev.starts_at) then
      raise exception 'Registrations are closed for this event' using errcode = 'check_violation';
    end if;
    if new.status not in ('PENDING_PAYMENT', 'CONFIRMED', 'WAITLISTED') then
      raise exception 'New registrations must be pending, confirmed or waitlisted' using errcode = 'check_violation';
    end if;
    if ev.pricing <> 'FREE' and new.status = 'CONFIRMED' then
      raise exception 'Paid registrations are confirmed by payment' using errcode = 'check_violation';
    end if;
  end if;

  -- The message is matched by the API layer to answer "event full" (409).
  if takes_seat and ev.capacity is not null and public.event_seats_taken(new.event_id) >= ev.capacity then
    raise exception 'EVENT_FULL' using errcode = 'check_violation';
  end if;

  return new;
end;
$$;
create trigger registrations_enforce_rules before insert or update on public.registrations
  for each row execute function public.enforce_registration_rules();

-- ---------------------------------------------------------------------------
-- payments — never store card data
-- ---------------------------------------------------------------------------
create table public.payments (
  id                   uuid primary key default gen_random_uuid(),
  registration_id      uuid not null references public.registrations (id) on delete restrict,
  provider             text not null default 'RAZORPAY',
  provider_order_id    text not null unique,
  provider_payment_id  text unique, -- unique ⇒ duplicate webhooks cannot double-apply
  amount               integer not null check (amount >= 0), -- paise
  currency             char(3) not null default 'INR',
  status               public.payment_status not null default 'CREATED',
  refund_status        public.refund_status not null default 'NONE',
  refund_amount        integer not null default 0 check (refund_amount >= 0),
  provider_refund_id   text unique,
  raw_reference        jsonb,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  check (refund_amount <= amount)
);
create index payments_registration_idx on public.payments (registration_id);
create trigger payments_updated_at before update on public.payments
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- notifications
-- ---------------------------------------------------------------------------
create table public.notifications (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references public.users (id) on delete cascade,
  registration_id  uuid references public.registrations (id) on delete set null,
  event_id         uuid references public.events (id) on delete set null,
  type             text not null,
  channel          public.notification_channel not null,
  status           public.notification_status not null default 'PENDING',
  message          text,
  sent_at          timestamptz,
  created_at       timestamptz not null default now()
);
create index notifications_user_idx on public.notifications (user_id);

-- ---------------------------------------------------------------------------
-- platform_settings — business rules are configuration, not code
-- ---------------------------------------------------------------------------
create table public.platform_settings (
  id          uuid primary key default gen_random_uuid(),
  key         text not null unique,
  value       jsonb not null,
  updated_at  timestamptz not null default now()
);
create trigger platform_settings_updated_at before update on public.platform_settings
  for each row execute function public.set_updated_at();

-- ===== 20261024000002_auth_roles_rls.sql =====
-- Auth integration, role helpers and Row Level Security.
--
-- Principle: the browser (anon / authenticated roles) may only touch its own
-- data, and only the columns listed below. Money, registration, check-in and
-- payout state are written exclusively by trusted server code (service role).

-- ---------------------------------------------------------------------------
-- Role helpers (security definer so policies can call them without recursion)
-- ---------------------------------------------------------------------------
create function public.current_user_role()
returns public.user_role
language sql
stable
security definer
set search_path = ''
as $$
  select role from public.users where id = auth.uid() and status = 'ACTIVE';
$$;

create function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.current_user_role() = 'ADMIN', false);
$$;

create function public.is_community_host(target_community_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.community_hosts h
    join public.users u on u.id = h.user_id and u.status = 'ACTIVE'
    where h.community_id = target_community_id and h.user_id = auth.uid()
  );
$$;

create function public.is_community_owner(target_community_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.community_hosts h
    where h.community_id = target_community_id and h.user_id = auth.uid() and h.role = 'OWNER'
  );
$$;

create function public.is_event_host(target_event_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.events e
    where e.id = target_event_id and public.is_community_host(e.community_id)
  );
$$;

-- ---------------------------------------------------------------------------
-- auth.users → public.users
-- A signup may request ORGANIZER; anything else (including ADMIN) becomes
-- MEMBER. Admins are promoted manually (see docs/DAILY-OPERATIONS.md).
-- ---------------------------------------------------------------------------
create function public.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
begin
  insert into public.users (id, email, phone, name, avatar_url, role)
  values (
    new.id,
    nullif(new.email, ''),
    nullif(new.phone, ''),
    left(coalesce(meta ->> 'full_name', meta ->> 'name'), 120),
    meta ->> 'avatar_url',
    case when meta ->> 'requested_role' = 'ORGANIZER'
      then 'ORGANIZER'::public.user_role
      else 'MEMBER'::public.user_role
    end
  );
  return new;
end;
$$;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_auth_user();

create function public.sync_auth_user_contact()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.users
     set email = nullif(new.email, ''),
         phone = nullif(new.phone, '')
   where id = new.id;
  return new;
end;
$$;
create trigger on_auth_user_contact_changed
  after update of email, phone on auth.users
  for each row execute function public.sync_auth_user_contact();

-- ---------------------------------------------------------------------------
-- Role-change RPCs
-- ---------------------------------------------------------------------------

-- Any active member may start running a community. Organisers still attend
-- other people's events, so nothing is lost by switching.
create function public.become_organizer()
returns public.user_role
language plpgsql
security definer
set search_path = ''
as $$
declare
  result public.user_role;
begin
  update public.users u
     set role = 'ORGANIZER'
   where u.id = auth.uid()
     and u.role = 'MEMBER'
     and u.status = 'ACTIVE'
  returning u.role into result;

  return coalesce(result, public.current_user_role());
end;
$$;

create function public.admin_set_user_role(target_user_id uuid, new_role public.user_role)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'Admin only' using errcode = 'insufficient_privilege';
  end if;
  update public.users set role = new_role where id = target_user_id;
end;
$$;

revoke execute on function public.become_organizer() from public, anon;
revoke execute on function public.admin_set_user_role(uuid, public.user_role) from public, anon;
grant execute on function public.become_organizer() to authenticated;
grant execute on function public.admin_set_user_role(uuid, public.user_role) to authenticated;
revoke execute on function public.handle_new_auth_user() from public, anon, authenticated;
revoke execute on function public.sync_auth_user_contact() from public, anon, authenticated;
revoke execute on function public.add_owner_as_host() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Table & column privileges (RLS then filters rows)
-- ---------------------------------------------------------------------------
revoke all on all tables in schema public from anon, authenticated;

grant select on public.categories, public.cities, public.communities, public.events
  to anon, authenticated;
grant select on public.users, public.community_hosts, public.community_members,
                public.registrations, public.payments, public.notifications
  to authenticated;

grant update (name, phone, avatar_url) on public.users to authenticated;

grant insert (owner_id, category_id, city_id, name, slug, tagline, description, logo_url,
              cover_image_url, instagram_handle, whatsapp_group_url, visibility)
  on public.communities to authenticated;
grant update (category_id, city_id, name, tagline, description, logo_url, cover_image_url,
              instagram_handle, whatsapp_group_url, visibility)
  on public.communities to authenticated;

-- Owners add/remove co-hosts; the OWNER row itself is managed by triggers.
grant insert (community_id, user_id), delete on public.community_hosts to authenticated;

-- People join and leave communities themselves.
grant insert (community_id, user_id), update (status) on public.community_members to authenticated;

grant insert (community_id, city_id, title, slug, description, cover_image_url, venue_name,
              venue_address, maps_url, starts_at, ends_at, capacity, pricing, price,
              waitlist_enabled, registration_closes_at, created_by)
  on public.events to authenticated;
grant update (city_id, title, description, cover_image_url, venue_name, venue_address, maps_url,
              starts_at, ends_at, capacity, pricing, price, waitlist_enabled,
              registration_closes_at, status)
  on public.events to authenticated;

-- registrations, payments, notifications: read-only from the browser.
-- platform_settings: no browser access at all; read on the server.

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
alter table public.users             enable row level security;
alter table public.cities            enable row level security;
alter table public.categories        enable row level security;
alter table public.communities       enable row level security;
alter table public.community_hosts   enable row level security;
alter table public.community_members enable row level security;
alter table public.events            enable row level security;
alter table public.registrations     enable row level security;
alter table public.payments          enable row level security;
alter table public.notifications     enable row level security;
alter table public.platform_settings enable row level security;

-- users
create policy users_select_self_or_admin on public.users
  for select to authenticated
  using (id = (select auth.uid()) or public.is_admin());
create policy users_update_self on public.users
  for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

-- cities / categories
create policy cities_select on public.cities
  for select to anon, authenticated
  using (is_active or public.is_admin());
create policy categories_select on public.categories
  for select to anon, authenticated
  using (is_active or public.is_admin());

-- communities: UNLISTED ones are readable by link; discovery filters PUBLIC.
create policy communities_select on public.communities
  for select to anon, authenticated
  using (status = 'ACTIVE' or public.is_community_host(id) or public.is_admin());
create policy communities_insert_organizer on public.communities
  for insert to authenticated
  with check (
    owner_id = (select auth.uid())
    and public.current_user_role() in ('ORGANIZER', 'ADMIN')
  );
create policy communities_update_host on public.communities
  for update to authenticated
  using (public.is_community_host(id))
  with check (public.is_community_host(id));

-- community_hosts
create policy community_hosts_select on public.community_hosts
  for select to authenticated
  using (public.is_community_host(community_id) or public.is_admin());
create policy community_hosts_insert_owner on public.community_hosts
  for insert to authenticated
  with check (public.is_community_owner(community_id) and role = 'CO_HOST');
create policy community_hosts_delete_owner on public.community_hosts
  for delete to authenticated
  using (public.is_community_owner(community_id) and role = 'CO_HOST');

-- community_members
create policy community_members_select on public.community_members
  for select to authenticated
  using (user_id = (select auth.uid()) or public.is_community_host(community_id) or public.is_admin());
create policy community_members_join_self on public.community_members
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.communities c where c.id = community_id and c.status = 'ACTIVE')
  );
-- members may leave/rejoin (unless banned); hosts may ban and unban
create policy community_members_update on public.community_members
  for update to authenticated
  using ((user_id = (select auth.uid()) and status <> 'BANNED') or public.is_community_host(community_id))
  with check (
    (user_id = (select auth.uid()) and status in ('ACTIVE', 'LEFT'))
    or public.is_community_host(community_id)
  );

-- events: drafts are visible to hosts only
create policy events_select on public.events
  for select to anon, authenticated
  using (
    (status <> 'DRAFT'
      and exists (select 1 from public.communities c where c.id = community_id and c.status = 'ACTIVE'))
    or public.is_community_host(community_id)
    or public.is_admin()
  );
create policy events_insert_host on public.events
  for insert to authenticated
  with check (public.is_community_host(community_id) and created_by = (select auth.uid()));
create policy events_update_host on public.events
  for update to authenticated
  using (public.is_community_host(community_id))
  with check (public.is_community_host(community_id));

-- registrations: attendees see their own; hosts see their events' guest list
create policy registrations_select on public.registrations
  for select to authenticated
  using (user_id = (select auth.uid()) or public.is_event_host(event_id) or public.is_admin());

-- payments: attendees see their own; admins see all (hosts get totals via server)
create policy payments_select on public.payments
  for select to authenticated
  using (
    exists (select 1 from public.registrations r
            where r.id = registration_id and r.user_id = (select auth.uid()))
    or public.is_admin()
  );

-- notifications
create policy notifications_select on public.notifications
  for select to authenticated
  using (user_id = (select auth.uid()) or public.is_admin());

-- platform_settings: RLS on, no policies ⇒ only the service role can read/write.

